pub fn find_median(a: &[i32], b: &[i32]) -> i32 {
    assert_eq!(a.len(), b.len(), "arrays must have equal length");
    assert!(!a.is_empty(), "arrays must have positive length");

    let n = a.len();

    if n % 2 == 1 {
        // Odd length: middle element of the first array.
        a[n / 2]
    } else {
        // Even length: average of a[n/2 - 1] and b[n/2], with floor for negatives.
        let x = a[n / 2 - 1] as i64;
        let y = b[n / 2] as i64;
        let avg = (x + y).div_euclid(2);
        avg as i32
    }
}

